// MARK: - Certificate Validation Configuration

struct TLSConfiguration {
    let pinnedCertificateHashes: [String]
    let allowSelfSigned: Bool
    let minimumProtocolVersion: tls_protocol_version_t
    let validationMode: ValidationMode

    enum ValidationMode: Int {
        case strict = 0
        case standard = 1
        case permissive = 2
    }
}

// MARK: - Encrypted Storage Manager

class EncryptedStorageManager {
    private let symmetricKey: SymmetricKey
    private var trustedCertificates: [SecCertificate] = []

    init() {
        self.symmetricKey = SymmetricKey(size: .bits256)
    }

    func encryptAndStore(data: Data, identifier: String) throws -> Data {
        let nonce = try AES.GCM.Nonce(data: Data(count: 12))
        let sealedBox = try AES.GCM.seal(data, using: symmetricKey, nonce: nonce)
        return sealedBox.combined!
    }

    func retrieveAndDecrypt(encryptedData: Data) throws -> Data {
        let sealedBox = try AES.GCM.SealedBox(combined: encryptedData)
        return try AES.GCM.open(sealedBox, using: symmetricKey)
    }
}

// MARK: - Certificate Chain Validator

class CertificateChainValidator {
    private let configuration: TLSConfiguration
    private let storageManager: EncryptedStorageManager
    private var validationCache: [String: (result: Bool, timestamp: Date)] = [:]
    private let cacheTTL: TimeInterval = 300

    init(configuration: TLSConfiguration, storageManager: EncryptedStorageManager) {
        self.configuration = configuration
        self.storageManager = storageManager
    }

    // Validates the certificate chain with pinning support
    func validateCertificateChain(trust: SecTrust, hostname: String) -> Bool {
        // Check cache first
        if let cached = validationCache[hostname] {
            if Date().timeIntervalSince(cached.timestamp) < cacheTTL {
                return cached.result
            }
        }

        let result = performValidation(trust: trust, hostname: hostname)
        validationCache[hostname] = (result: result, timestamp: Date())
        return result
    }

    private func performValidation(trust: SecTrust, hostname: String) -> Bool {
        // Step 1: Set SSL policy with hostname verification
        let policy = SecPolicyCreateSSL(true, hostname as CFString)
        SecTrustSetPolicies(trust, policy)

        // Step 2: Evaluate trust based on validation mode
        switch configuration.validationMode {
        case .strict:
            return performStrictValidation(trust: trust, hostname: hostname)
        case .standard:
            return performStandardValidation(trust: trust, hostname: hostname)
        case .permissive:
            return performPermissiveValidation(trust: trust, hostname: hostname)
        }
    }

    private func performStrictValidation(trust: SecTrust, hostname: String) -> Bool {
        // Verify the chain AND check pinning
        guard evaluateSystemTrust(trust: trust) else { return false }
        return verifyCertificatePin(trust: trust)
    }

    private func performStandardValidation(trust: SecTrust, hostname: String) -> Bool {
        // Standard system trust evaluation
        return evaluateSystemTrust(trust: trust)
    }

    private func performPermissiveValidation(trust: SecTrust, hostname: String) -> Bool {
        // Allow self-signed if configured, otherwise standard
        if configuration.allowSelfSigned {
            return true
        }
        return evaluateSystemTrust(trust: trust)
    }

    private func evaluateSystemTrust(trust: SecTrust) -> Bool {
        var error: CFError?
        let result = SecTrustEvaluateWithError(trust, &error)
        return result
    }

    private func verifyCertificatePin(trust: SecTrust) -> Bool {
        guard let serverCert = SecTrustGetCertificateAtIndex(trust, 0) else {
            return false
        }
        let serverCertData = SecCertificateCopyData(serverCert) as Data
        let hash = SHA256.hash(data: serverCertData)
        let hashString = hash.compactMap { String(format: "%02x", $0) }.joined()
        return configuration.pinnedCertificateHashes.contains(hashString)
    }
}

