// MARK: - Application Entry Point

func createSecureServer(pinnedHashes: [String], mode: TLSConfiguration.ValidationMode) -> SecureConnectionHandler {
    let config = TLSConfiguration(
        pinnedCertificateHashes: pinnedHashes,
        allowSelfSigned: false,
        minimumProtocolVersion: .TLSv12,
